long double squared(const Complex& z){const long double a=z.real(),b=z.imag();return a*a+b*b;}
std::vector<double> window(std::size_t n,const Json& options,const double* supplied,std::size_t count){require(n>=2,"A spectral window requires at least two samples.");if(count){require(count==n,"User window length differs from segment length.");return {supplied,supplied+n};}const auto type=text(options,"window","hann");std::vector<double> out(n,1);for(std::size_t j=0;j<n;++j){const double angle=2*std::acos(-1.)*j/(n-1);if(type=="hann")out[j]=.5-.5*std::cos(angle);else if(type=="hamming")out[j]=.54-.46*std::cos(angle);else if(type=="blackman")out[j]=.42-.5*std::cos(angle)+.08*std::cos(2*angle);else require(type=="rectangular","Window must be hann,hamming,blackman or rectangular.");}return out;}
void detrend(std::vector<Complex>& x,std::size_t n,const std::string& mode){require(mode=="none"||mode=="constant"||mode=="linear","detrend must be none,constant or linear.");if(mode=="none")return;Complex mean=0,slope=0;for(std::size_t i=0;i<n;++i)mean+=x[i]/double(n);if(mode=="linear"){long double denominator=0;const double center=(n-1)*.5;for(std::size_t i=0;i<n;++i){const auto d=i-center;slope+=d*(x[i]-mean);denominator+=d*d;}if(denominator>0)slope/=double(denominator);}for(std::size_t i=0;i<n;++i)x[i]-=mean+slope*(double(i)-(n-1)*.5);}
